cases.good:
// shell keeps native display; only metrics are pinned
playerShell.style.setProperty('height','100%','important');
let n = videoEl.parentElement;
while (n && n !== playerShell && n !== document.body) {
  n.style.setProperty('width','100%','important');
  n.style.setProperty('height','100%','important');
  n.style.setProperty('min-height','0','important');
  n = n.parentElement;
}
videoEl.style.setProperty('height','100%','important');
